export const KIT_SPRITES: Partial<Record<TemplateId, KitSprites>> = {};

export interface Kit2D {
  /** Ground tile keys in KIT_SPRITES[kit].sprites. */
  tiles: { grass: string; grassAlt: string; path: string; sand: string; stone: string; water: string; cliff: string; cliffSand: string };
  trees: string[]; scatter: string[]; rocks: string[]; props: string[];
  landmarks: Record<string, string>;
  /** archetype -> CHAR_SPRITES key (unknown -> npcBodies.kid) */
  npcBodies: Record<string, string>;
  companion: string;
  player: string;
  goat: string;
  palette: { ground: string; groundAlt: string; path: string; water: string; sky: [string, string]; fog: string; sun: string; ink: string; glow: string };
  ambience: string;
}

const T = { grass: 'tile.grass', grassAlt: 'tile.grassAlt', path: 'tile.path', sand: 'tile.sand', stone: 'tile.stone', water: 'tile.water', cliff: 'tile.cliff', cliffSand: 'tile.cliffSand' };
const PURPLE_SKY: Record<TemplateId, [string, string]> = {
  forest: ['#5b3f9e', '#f3c6e8'], space: ['#120a2e', '#4a2a86'], math: ['#6a4ab0', '#ffd6e8'],
  egypt: ['#7a4aa8', '#ffcf9e'], ocean: ['#4a4fb0', '#bfe6ff'], lab: ['#6d5ab8', '#e8dcff'],
};
function to2D(id: TemplateId): Kit2D {
  const k = KITS[id];
  const has = (s: string) => !!KIT_SPRITES[id]?.sprites[s] || !!CHAR_SPRITES[s];
  const f = (a: string[]) => a.filter(has);
  const npc: Record<string, string> = {};
  for (const [arch, key] of Object.entries(k.npcBodies)) npc[arch] = CHAR_SPRITES[key] ? key : 'npc.kid';
  return {
    tiles: T, trees: f(k.trees), scatter: f(k.scatter), rocks: f(k.rocks), props: f(k.props ?? []),
    landmarks: Object.fromEntries(Object.entries(k.landmarks).filter(([, v]) => has(v))),
    npcBodies: npc, companion: CHAR_SPRITES[k.companion] ? k.companion : 'companion', player: 'player', goat: 'goat',
    palette: { ground: k.ground, groundAlt: k.groundAlt, path: k.path, water: k.water, sky: PURPLE_SKY[id], fog: '#8a6cc8', sun: '#ffd9a8', ink: '#261440', glow: '#ffd36b' },
    ambience: k.ambience,
  };
}
export const KITS2D: Record<TemplateId, Kit2D> = {
  forest: to2D('forest'), space: to2D('space'), math: to2D('math'), egypt: to2D('egypt'), ocean: to2D('ocean'), lab: to2D('lab'),
};

/** Pick the 8-way direction from a screen-space velocity (dx right, dy down). */
export function dirFromVector(dx: number, dy: number): Dir8 {
  const a = Math.atan2(dy, dx); // 0 = E, pi/2 = S
  const i = (Math.round(a / (Math.PI / 4)) + 8) % 8;
  return (['E', 'SE', 'S', 'SW', 'W', 'NW', 'N', 'NE'] as Dir8[])[i];
}
